style.css:
@-moz-document domain("music.youtube.com") {
body, ytmusic-app {
    background-color: #1c1c1c !important;
    color: #ffffff !important;
    font-family: 'Gotham', sans-serif !important;
  }

  /* Barra superior al estilo Spotify */
  ytmusic-nav-bar, ytmusic-player-bar {
    background-color: #1c1c1c !important;
    box-shadow: 0 2px 8px rgba(0,0,0,0.6);
    border-top: 2px solid #cc3333 !important;
  }

  /* Controles y botones */
  paper-icon-button, .ytmusic-icon-button {
    color: #cc3333 !important;
    transition: color 0.3s ease;
  }

  paper-icon-button:hover, .ytmusic-icon-button:hover {
    color: #ff4d4d !important;
  }

  /* Recuadros de contenido */
  ytmusic-responsive-list-item-renderer,
  ytmusic-grid-renderer {
    background-color: #242424 !important;
    border-radius: 12px;
    padding: 8px;
    margin-bottom: 12px;
  }

  /* Enlaces y textos interactivos */
  a, .yt-simple-endpoint {
    color: #ffffff !important;
    text-decoration: none !important;
  }

  a:hover, .yt-simple-endpoint:hover {
    color: #ff4d4d !important;
  }

  /* Pistas activas y foco */
  .selected, .focused {
    border-left: 4px solid #cc3333 !important;
    background-color: #2a2a2a !important;
  }

  /* Scroll personalizado */
  ::-webkit-scrollbar {
    width: 8px;
  }

  ::-webkit-scrollbar-thumb {
    background-color: #cc3333;
    border-radius: 4px;
  }

  /* Oculta publicidad */
  ytmusic-guide-entry-renderer[has-ad] {
    display: none !important;
  }
}
